import re, subprocess, sys
files = subprocess.run(['git','ls-tree','-r','--name-only','origin/main'],capture_output=True,text=True).stdout.split()
eps = [f for f in files if re.match(r'^S\d+/E\d+\.md$',f)]
bad=0
for f in sorted(eps):
    txt = subprocess.run(['git','show',f'origin/main:{f}'],capture_output=True,text=True).stdout
    m = re.match(r'^---\n(.*?)\n---\n\n(.*?)\n\n', txt, re.S)
    if not m:
        print(f'{f}: FRONTMATTER/PARAGRAPH PARSE FAIL'); bad+=1; continue
    fm, para = m.group(1), m.group(2).strip()
    sm = re.search(r'^summary: "(.*)"$', fm, re.M)
    ti = re.search(r'^title: "(.*)"$', fm, re.M)
    st = re.search(r'^status: (\S+)$', fm, re.M)
    issues=[]
    if not sm: issues.append('no summary')
    else:
        if sm.group(1).strip()!=para: issues.append('paragraph != summary')
        w=len(sm.group(1).split())
        if not (15<=w<=40): issues.append(f'summary words={w}')
    if not ti: issues.append('no title')
    elif not ti.group(1).startswith('The One With'): issues.append('title style')
    if not st: issues.append('no status')
    if issues:
        print(f'{f}: {"; ".join(issues)}'); bad+=1
print(f'checked {len(eps)} files, {bad} with issues')
