import re, subprocess
def git(a,c='/tmp/main-wt'): return subprocess.run(['git']+a,cwd=c,capture_output=True,text=True).stdout
files = git(['ls-tree','-r','--name-only','origin/main']).split()
eps = sorted([f for f in files if re.match(r'^S\d+/E\d+\.md$',f)], key=lambda s:(int(s.split('/')[0][1:]),int(s.split('/')[1][1:].split('.')[0])))
issues=[]
for f in eps:
    txt = git(['show',f'origin/main:{f}'])
    lines = txt.split('\n')
    for i,l in enumerate(lines):
        if re.match(r'^\*\*[A-Z][a-z]+\*\* \(\d{4}-', l):
            if i>0 and lines[i-1].strip()!='':
                issues.append((f,i+1,'missing blank line before',lines[i-1][:50]))
        if l.startswith('Source: friend/'):
            if i>0 and lines[i-1].strip()!='':
                issues.append((f,i+1,'missing blank before Source',lines[i-1][:40]))
            if i+1<len(lines) and lines[i+1].strip()!='':
                issues.append((f,i+1,'missing blank after Source',lines[i+1][:40]))
        if l.rstrip()!=l:
            issues.append((f,i+1,'trailing whitespace',repr(l[-20:])))
for x in issues[:20]: print(x)
print('format issues:',len(issues))
